const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\\':'&#92;','"':'&quot;'}[c]));
const peso=n=>'₱'+Number(n||0).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});
const dateFmt=d=>d?new Date(d).toLocaleDateString('en-PH',{year:'numeric',month:'short',day:'2-digit'}):'—';
const uid=()=>Math.random().toString(36).slice(2)+Date.now().toString(36);
let state={token:localStorage.getItem('hrisToken')||'',user:null,permissions:[],settings:null,data:{},page:'dashboard',query:'',modal:null,editing:null,drawer:null};

const nav=[
  ['Core','dashboard','⌂','Dashboard'],['','employees','♙','Employees / 201 Files'],['Timekeeping','timekeeping','◷','Timekeeping / DTR'],['','schedules','⇄','Schedules'],['','holidays','▦','Holidays'],
  ['Payroll & Benefits','payroll','₱','Payroll'],['','payrollPeriods','▣','Payroll Periods'],['','payslips','▤','Payslips'],['','thirteenth','13','13th Month'],['','leave','◴','Leave Management'],['','loans','◆','Loans & Deductions'],
  ['Organization','branches','⌘','Branches'],['','departments','☷','Departments'],['','positions','◎','Positions'],['','workGroups','◍','Employee Groups'],['Reports','reports','◈','Reports'],['Security','security','♜','Users & Access'],['','audit','⌁','Audit Trail'],['System','settings','⚙','Settings']
];
function has(p){return state.permissions.includes('*')||state.permissions.includes(p)||state.permissions.includes(p.split(':')[0]);}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.classList.remove('show'),2800)}
async function api(path,opts={}){opts.headers={...(opts.headers||{}),'Content-Type':'application/json'};if(state.token)opts.headers['x-session-token']=state.token;const r=await fetch(path,opts);let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||`Request failed (${r.status})`);return d;}
async function login(e){e.preventDefault();try{const r=await api('/api/login',{method:'POST',body:JSON.stringify({username:$('#username').value.trim(),password:$('#password').value,companyCode:$('#company').value.trim()||'DEGZ'})});state.token=r.token;state.user=r.user;localStorage.setItem('hrisToken',state.token);await load();toast('Welcome back');}catch(err){toast(err.message)}}
async function load(){try{const b=await api('/api/bootstrap');state.user=b.user;state.permissions=b.permissions;state.settings=b.settings;state.data=b.data;try{state.data.audit=(await api('/api/audit')).rows||[]}catch{}render();}catch(err){localStorage.removeItem('hrisToken');state.token='';render();toast(err.message)}}
async function logout(){try{await api('/api/logout',{method:'POST'})}catch{}localStorage.removeItem('hrisToken');state.token='';state.user=null;render()}
function shell(){return `<div class="layout"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-mark">D</div><div><div class="logo-title">DEGZ HRIS</div><div class="small muted">Enterprise Payroll</div></div></div>${navHtml()}<div class="sidebar-foot"><div class="small muted">Signed in as</div><strong>${esc(state.user?.name||'User')}</strong><div class="small muted">${esc(state.user?.role||'')}</div></div></aside><main class="main"><header class="topbar"><div class="topbar-left"><button class="btn ghost menu-btn" onclick="toggleSide()">☰</button><div><h2>${pageTitle()}</h2><div class="small muted">${esc(state.settings?.company?.name||'Company')}</div></div></div><div class="topbar-right"><button class="btn ghost" onclick="toggleTheme()">◐</button><button class="btn ghost" onclick="refreshData()">↻</button><div class="avatar">${esc((state.user?.name||'U').split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><button class="btn ghost" onclick="logout()">Logout</button></div></header><section class="content" id="content"></section></main><div class="mobile-nav">${[['dashboard','⌂'],['employees','♙'],['timekeeping','◷'],['payroll','₱'],['reports','◈']].map(([p,i])=>`<button onclick="go('${p}')"><span class="icon">${i}</span>${p}</button>`).join('')}</div></div><div id="modalRoot"></div>`}
function navHtml(){let last='';return nav.filter(x=>state.user?.role==='employee'?['dashboard','employees','timekeeping','leave','payslips'].includes(x[1]):true).map(x=>{const [section,p,icon,label]=x;let h='';if(section&&section!==last){h+=`<div class="nav-section">${section}</div>`;last=section}h+=`<button class="nav-item ${state.page===p?'active':''}" onclick="go('${p}')"><span class="icon">${icon}</span><span>${label}</span></button>`;return h}).join('')}
function pageTitle(){const x=nav.find(n=>n[1]===state.page);return x?x[3]:'Dashboard'}
function render(){if(!state.token||!state.user){$('#app').innerHTML=loginView();return}$('#app').innerHTML=shell();renderPage();}
function loginView(){return `<div class="login"><div class="login-box"><div class="brand"><div class="brand-mark">D</div><div><div class="logo-title">DEGZ Enterprise HRIS</div><div class="small muted">HR • Timekeeping • Payroll</div></div></div><h1>Sign in</h1><p>Secure workspace for Philippine HR and payroll operations.</p><form onsubmit="login(event)"><div class="field"><label>Company Code / Name</label><input id="company" value="DEGZ" autocomplete="organization"/></div><div class="field"><label>Username</label><input id="username" value="admin" autocomplete="username" required/></div><div class="field"><label>Password</label><input id="password" value="admin123" type="password" autocomplete="current-password" required/></div><button class="btn primary" style="width:100%;padding:12px">Sign in</button></form><div class="notice" style="margin-top:18px">Demo admin: <b>admin / admin123</b><br/>HR: <b>hr / hr123</b> • Payroll: <b>payroll / payroll123</b></div></div></div>`}
async function refreshData(){await load();toast('Data refreshed')}
function toggleSide(){$('#sidebar')?.classList.toggle('open')}
function toggleTheme(){document.body.classList.toggle('dark');localStorage.setItem('hrisTheme',document.body.classList.contains('dark')?'dark':'light')}
if(localStorage.getItem('hrisTheme')==='dark')document.body.classList.add('dark');
function go(p){state.page=p;state.query='';render();$('#sidebar')?.classList.remove('open')}
function card(k,v,s=''){return `<div class="card kpi"><div class="lbl">${k}</div><div class="num">${v}</div><div class="sub">${s}</div></div>`}
function panel(title,body,extra=''){return `<div class="card panel"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><h3>${title}</h3>${extra}</div>${body}</div>`}
function badge(s){const x=String(s||'').toLowerCase().replace(/\s+/g,'-');return `<span class="badge ${x}">${esc(s||'—')}</span>`}
function renderPage(){const fn={dashboard:dashboardPage,employees:employeesPage,'201files':employeesPage,timekeeping:timekeepingPage,schedules:schedulesPage,holidays:holidaysPage,payroll:payrollPage,payrollPeriods:payrollPeriodsPage,payslips:payslipsPage,thirteenth:thirteenthPage,leave:leavePage,loans:loansPage,branches:branchesPage,departments:departmentsPage,positions:positionsPage,workGroups:workGroupsPage,reports:reportsPage,security:securityPage,audit:auditPage,settings:settingsPage};const out=(fn[state.page]||dashboardPage)(); if(out&&typeof out.then==='function'){out.then(html=>$('#content').innerHTML=html)}else $('#content').innerHTML=out;}
function dashboardPage(){const d=state.data;const emps=(d.employees||[]).filter(e=>e.status==='Active');const att=d.attendance||[];const leaves=d.leaveRequests||[];const prs=d.payrollRecords||[];const today=new Date().toISOString().slice(0,10);const a=att.filter(x=>x.date===today);const gross=prs.reduce((s,x)=>s+Number(x.grossPay||0),0);return `<div class="page-head"><div><h1>Good day, ${esc((state.user?.name||'User').split(' ')[0])}.</h1><div class="muted">Monitor workforce, attendance and payroll in one place.</div></div><div class="actions"><button class="btn primary" onclick="openEmployeeForm()">＋ Add Employee</button><button class="btn" onclick="go('payrollPeriods')">Run Payroll</button></div></div><div class="grid kpis">${card('Active Employees',emps.length,'Current workforce')}${card('Present Today',a.filter(x=>x.status==='Present'||x.status==='Late').length,'Attendance')}${card('Absent Today',a.filter(x=>x.status==='Absent').length,'Attendance')}${card('Pending Leave',leaves.filter(x=>x.status==='Pending').length,'Approval queue')}${card('Payroll Cost',peso(gross),'Loaded payroll records')}${card('Overtime Hours',att.reduce((s,x)=>s+Number(x.otHours||0),0).toFixed(1),'Imported / encoded')}</div><div class="grid dashboard-grid"><div>${panel('Payroll Trend',payrollChart())}${panel('Branch Summary',branchSummary(),'<button class="btn ghost" onclick="go(\'branches\')">Manage</button>')}</div><div>${panel('Approval Queue',approvalQueue())}${panel('Quick Actions',quickActions())}</div></div>`}
function payrollChart(){const prs=state.data.payrollRecords||[];const pids=[...new Set(prs.map(x=>x.periodId))].slice(-8);let vals=pids.map(id=>{const rows=prs.filter(x=>x.periodId===id);return {id,total:rows.reduce((s,x)=>s+Number(x.grossPay||0),0)}});const max=Math.max(1,...vals.map(x=>x.total));return `<div class="chart-wrap">${vals.length?vals.map(v=>`<div class="bar" style="height:${Math.max(8,v.total/max*190)}px"><span>${peso(v.total/1000).replace('₱','₱')}k</span></div>`).join(''):`<div class="empty">No payroll records yet. Generate a payroll period to populate this chart.</div>`}</div>`}
function branchSummary(){const branches=state.data.branches||[], emps=state.data.employees||[];return `<div class="list">${branches.map(b=>{const n=emps.filter(e=>e.branchId===b.id&&e.status==='Active').length;return `<div class="list-row"><div><strong>${esc(b.name)}</strong><div class="small muted">${esc(b.code||'')}</div></div><strong>${n}</strong></div>`}).join('')||'<div class="empty">No branches.</div>'}</div>`}
function approvalQueue(){const l=(state.data.leaveRequests||[]).filter(x=>x.status==='Pending').slice(0,5);const p=(state.data.payrollPeriods||[]).filter(x=>x.status==='Computed').slice(0,3);return `<div class="list">${l.map(x=>`<div class="list-row"><div><strong>Leave • ${esc(x.employeeName||x.employeeId)}</strong><div class="small muted">${dateFmt(x.startDate)} – ${dateFmt(x.endDate)}</div></div>${badge('Pending')}</div>`).join('')}${p.map(x=>`<div class="list-row"><div><strong>Payroll • ${esc(x.name)}</strong><div class="small muted">Ready for approval</div></div>${badge('Pending')}</div>`).join('')}${!l.length&&!p.length?'<div class="empty">No items waiting for approval.</div>':''}</div>`}
function quickActions(){return `<div class="grid stat-grid"><button class="btn" onclick="openEmployeeForm()">Add Employee</button><button class="btn" onclick="go('timekeeping')">Encode DTR</button><button class="btn" onclick="go('leave')">Review Leave</button><button class="btn" onclick="go('payrollPeriods')">Create Cutoff</button><button class="btn" onclick="go('reports')">Open Reports</button><button class="btn" onclick="go('settings')">Payroll Settings</button></div>`}

const entityConfig={
 branches:{title:'Branches / Locations',key:'branches',fields:[['name','Branch Name','text'],['code','Code','text'],['address','Address','text'],['active','Active','checkbox']]},
 departments:{title:'Departments',key:'departments',fields:[['name','Department Name','text'],['code','Code','text'],['active','Active','checkbox']]},
 positions:{title:'Positions',key:'positions',fields:[['name','Position Name','text'],['code','Code','text'],['departmentId','Department','select:departments'],['active','Active','checkbox']]},
 workGroups:{title:'Employee Groups',key:'workGroups',fields:[['name','Group Name','text'],['code','Code','text'],['scheduleName','Default Schedule','text'],['otMultiplier','OT Multiplier','number'],['holidayMultiplier','Holiday Multiplier','number'],['nightDiffRate','Night Diff Rate','number'],['active','Active','checkbox']]},
 schedules:{title:'Shifting Schedules',key:'schedules',fields:[['name','Schedule Name','text'],['start','Time In','time'],['end','Time Out','time'],['breakMinutes','Break Minutes','number'],['graceMinutes','Grace Minutes','number'],['restDays','Rest Days (0=Sun…6=Sat)','text'],['active','Active','checkbox']]},
 holidays:{title:'Holiday Calendar',key:'holidays',fields:[['date','Date','date'],['name','Holiday Name','text'],['type','Type','selectOptions:regular|special'],['multiplier','Multiplier','number'],['active','Active','checkbox']]},
 leaveTypes:{title:'Leave Types',key:'leaveTypes',fields:[['name','Leave Name','text'],['code','Code','text'],['defaultDays','Default Days','number'],['paid','Paid','checkbox'],['active','Active','checkbox']]},
}
function genericPage(kind){const cfg=entityConfig[kind];const rows=state.data[cfg.key]||[];const q=state.query.toLowerCase();const filtered=rows.filter(r=>JSON.stringify(r).toLowerCase().includes(q));const cols=cfg.fields.filter(f=>f[0]!=='active').slice(0,5);return `<div class="page-head"><div><h1>${cfg.title}</h1><div class="muted">Manage ${cfg.title.toLowerCase()} and operational rules.</div></div><div class="actions"><button class="btn primary" onclick="openGenericForm('${kind}')">＋ Add</button></div></div><div class="card panel"><div class="toolbar"><input placeholder="Search…" value="${esc(state.query)}" oninput="state.query=this.value;renderPage()"/><button class="btn" onclick="downloadCSV('${cfg.key}')">Export CSV</button></div><div class="table-wrap"><table class="table"><thead><tr>${cols.map(c=>`<th>${c[1]}</th>`).join('')}<th>Status</th><th>Actions</th></tr></thead><tbody>${filtered.map(r=>`<tr>${cols.map(c=>`<td>${esc(c[0].endsWith('Id')?nameFor(c[0],r[c[0]]):r[c[0]])}</td>`).join('')}<td>${badge(r.active===false?'Inactive':'Active')}</td><td><div class="row-actions"><button class="btn" onclick="openGenericForm('${kind}','${r.id}')">Edit</button><button class="btn danger" onclick="del('${cfg.key}','${r.id}')">Delete</button></div></td></tr>`).join('')||`<tr><td colspan="20"><div class="empty">No records found.</div></td></tr>`}</tbody></table></div></div>`}
function nameFor(field,id){const map={branchId:'branches',departmentId:'departments',positionId:'positions',scheduleId:'schedules',employeeId:'employees',leaveTypeId:'leaveTypes'};const arr=state.data[map[field]]||[];const x=arr.find(y=>y.id===id);if(!x)return id||'—';return x.name||`${x.firstName||''} ${x.lastName||''}`.trim()||id}
function branchesPage(){return genericPage('branches')}function departmentsPage(){return genericPage('departments')}function positionsPage(){return genericPage('positions')}function workGroupsPage(){return genericPage('workGroups')}function schedulesPage(){return genericPage('schedules')}function holidaysPage(){return genericPage('holidays')}

function employeesPage(){let rows=(state.data.employees||[]).filter(e=>JSON.stringify(e).toLowerCase().includes(state.query.toLowerCase()));if(state.statusFilter)rows=rows.filter(e=>e.status===state.statusFilter);return `<div class="page-head"><div><h1>Employees & 201 Files</h1><div class="muted">Masterlist, employment data, compensation, IDs and employee history.</div></div><div class="actions"><button class="btn" onclick="downloadCSV('employees')">Export CSV</button><button class="btn primary" onclick="openEmployeeForm()">＋ Add Employee</button></div></div><div class="card panel"><div class="toolbar"><input placeholder="Search employee no., name, branch…" value="${esc(state.query)}" oninput="state.query=this.value;renderPage()"/><select onchange="filterEmployeeStatus(this.value)"><option value="">All Status</option><option>Active</option><option>On Leave</option><option>Inactive</option></select></div><div class="table-wrap"><table class="table"><thead><tr><th>Employee No.</th><th>Employee</th><th>Employment</th><th>Branch</th><th>Department</th><th>Salary</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(e=>`<tr><td>${esc(e.employeeNo)}</td><td><strong>${esc(e.firstName+' '+(e.middleName?e.middleName+' ':'')+e.lastName)}</strong><div class="small muted">${esc(e.email||'')}</div></td><td>${esc(e.employmentType)}<div class="small muted">${dateFmt(e.hireDate)}</div></td><td>${esc(nameFor('branchId',e.branchId))}</td><td>${esc(nameFor('departmentId',e.departmentId))}</td><td>${peso(e.basicSalary)}</td><td>${badge(e.status)}</td><td><div class="row-actions"><button class="btn" onclick="openEmployeeDrawer('${e.id}')">View</button><button class="btn" onclick="openEmployeeForm('${e.id}')">Edit</button><button class="btn" onclick="openDocumentForm('${e.id}')">201 Doc</button></div></td></tr>`).join('')||`<tr><td colspan="20"><div class="empty">No employees found.</div></td></tr>`}</tbody></table></div></div>`}
function filterEmployeeStatus(v){state.statusFilter=v;renderPage()}
function openEmployeeForm(id){const e=id?(state.data.employees||[]).find(x=>x.id===id):null;state.editing=e||{};state.modal='employee';$('#modalRoot').innerHTML=employeeModal(e||{});$('#modalRoot').querySelector('.modal-backdrop').classList.add('show')}
function employeeModal(e){const sel=(arr,id)=>`<select name="${esc(arguments[2]||'')}" required></select>`;return `<div class="modal-backdrop show"><div class="modal wide"><div class="modal-head"><h3>${e.id?'Edit Employee':'Add Employee'}</h3><button class="btn ghost" onclick="closeModal()">✕</button></div><form onsubmit="saveEmployee(event,'${e.id||''}')"><div class="modal-body form-grid"><div class="field"><label>Employee No.</label><input name="employeeNo" value="${esc(e.employeeNo||'') }" placeholder="EMP-0004" required></div><div class="field"><label>Status</label><select name="status"><option ${e.status==='Active'?'selected':''}>Active</option><option ${e.status==='On Leave'?'selected':''}>On Leave</option><option ${e.status==='Inactive'?'selected':''}>Inactive</option></select></div><div class="field"><label>First Name</label><input name="firstName" value="${esc(e.firstName||'')}" required></div><div class="field"><label>Middle Name</label><input name="middleName" value="${esc(e.middleName||'')}"></div><div class="field"><label>Last Name</label><input name="lastName" value="${esc(e.lastName||'')}" required></div><div class="field"><label>Suffix</label><input name="suffix" value="${esc(e.suffix||'')}"></div><div class="field"><label>Email</label><input type="email" name="email" value="${esc(e.email||'')}"></div><div class="field"><label>Mobile</label><input name="mobile" value="${esc(e.mobile||'')}"></div><div class="field"><label>Birth Date</label><input type="date" name="birthDate" value="${esc(e.birthDate||'')}"></div><div class="field"><label>Civil Status</label><select name="civilStatus"><option>Single</option><option ${e.civilStatus==='Married'?'selected':''}>Married</option><option ${e.civilStatus==='Widowed'?'selected':''}>Widowed</option><option ${e.civilStatus==='Separated'?'selected':''}>Separated</option></select></div><div class="field"><label>Hire Date</label><input type="date" name="hireDate" value="${esc(e.hireDate||new Date().toISOString().slice(0,10))}" required></div><div class="field"><label>Employment Type</label><select name="employmentType"><option ${e.employmentType==='Regular'?'selected':''}>Regular</option><option ${e.employmentType==='Probationary'?'selected':''}>Probationary</option><option ${e.employmentType==='Project'?'selected':''}>Project</option><option ${e.employmentType==='Part-time'?'selected':''}>Part-time</option></select></div><div class="field"><label>Branch</label><select name="branchId" required>${(state.data.branches||[]).map(x=>`<option value="${x.id}" ${e.branchId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Department</label><select name="departmentId" required>${(state.data.departments||[]).map(x=>`<option value="${x.id}" ${e.departmentId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Position</label><select name="positionId" required>${(state.data.positions||[]).map(x=>`<option value="${x.id}" ${e.positionId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Work Group</label><select name="workGroup">${(state.data.workGroups||[{name:'Regular'}]).map(x=>`<option ${e.workGroup===(x.name||'')?'selected':''}>${esc(x.name||x)}</option>`).join('')}</select></div><div class="field"><label>Assigned Schedule</label><select name="scheduleId"><option value="">— Not Assigned —</option>${(state.data.schedules||[]).map(x=>`<option value="${x.id}" ${e.scheduleId===x.id?'selected':''}>${esc(x.name+' • '+x.start+'-'+x.end)}</option>`).join('')}</select></div><div class="field"><label>Pay Type</label><select name="payType"><option ${e.payType==='Monthly'?'selected':''}>Monthly</option><option ${e.payType==='Daily'?'selected':''}>Daily</option><option ${e.payType==='Hourly'?'selected':''}>Hourly</option></select></div><div class="field"><label>Basic Salary</label><input type="number" step="0.01" name="basicSalary" value="${e.basicSalary||0}" required></div><div class="field"><label>Monthly Allowances</label><input type="number" step="0.01" name="allowances" value="${e.allowances||0}"></div><div class="field"><label>SSS No.</label><input name="sssNo" value="${esc(e.sssNo||'')}"></div><div class="field"><label>PhilHealth No.</label><input name="philhealthNo" value="${esc(e.philhealthNo||'')}"></div><div class="field"><label>Pag-IBIG No.</label><input name="pagibigNo" value="${esc(e.pagibigNo||'')}"></div><div class="field"><label>TIN</label><input name="tinNo" value="${esc(e.tinNo||'')}"></div><div class="field full"><label>Address</label><textarea name="address" rows="2">${esc(e.address||'')}</textarea></div><div class="field"><label>Emergency Contact</label><input name="emergencyContact" value="${esc(e.emergencyContact||'')}"></div><div class="field"><label>Emergency Phone</label><input name="emergencyPhone" value="${esc(e.emergencyPhone||'')}"></div></div><div class="modal-foot"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save Employee</button></div></form></div></div>`}
async function saveEmployee(e,id){e.preventDefault();const f=new FormData(e.target);const obj=Object.fromEntries(f.entries());obj.basicSalary=Number(obj.basicSalary||0);obj.allowances=Number(obj.allowances||0);try{await api(id?`/api/employees/${id}`:'/api/employees',{method:id?'PUT':'POST',body:JSON.stringify(obj)});closeModal();await load();toast('Employee saved');}catch(err){toast(err.message)}}
function openEmployeeDrawer(id){const e=(state.data.employees||[]).find(x=>x.id===id);if(!e)return;const docs=(state.data.documents||[]).filter(x=>x.employeeId===id);const att=(state.data.attendance||[]).filter(x=>x.employeeId===id).slice(-8).reverse();const pays=(state.data.payrollRecords||[]).filter(x=>x.employeeId===id).slice(-5).reverse();$('#modalRoot').innerHTML=`<div class="modal-backdrop show" onclick="if(event.target===this)closeModal()"><div class="drawer show"><div class="drawer-head"><div><strong>${esc(e.firstName+' '+e.lastName)}</strong><div class="small muted">${esc(e.employeeNo)} • ${esc(e.positionId?nameFor('positionId',e.positionId):'')}</div></div><button class="btn ghost" onclick="closeModal()">✕</button></div><div class="drawer-body"><div class="notice">${badge(e.status)} ${esc(e.employmentType)} • ${esc(e.workGroup||'')}</div><h3>Personal Information</h3><div class="grid stat-grid"><div><span class="muted small">Email</span><div>${esc(e.email||'—')}</div></div><div><span class="muted small">Mobile</span><div>${esc(e.mobile||'—')}</div></div><div><span class="muted small">Birth Date</span><div>${dateFmt(e.birthDate)}</div></div><div><span class="muted small">Civil Status</span><div>${esc(e.civilStatus||'—')}</div></div><div><span class="muted small">Address</span><div>${esc(e.address||'—')}</div></div></div><h3 style="margin-top:20px">Employment & Compensation</h3><div class="grid stat-grid"><div><span class="muted small">Branch</span><div>${esc(nameFor('branchId',e.branchId))}</div></div><div><span class="muted small">Department</span><div>${esc(nameFor('departmentId',e.departmentId))}</div></div><div><span class="muted small">Basic Salary</span><div>${peso(e.basicSalary)}</div></div><div><span class="muted small">Allowances</span><div>${peso(e.allowances)}</div></div><div><span class="muted small">SSS</span><div>${esc(e.sssNo||'—')}</div></div><div><span class="muted small">TIN</span><div>${esc(e.tinNo||'—')}</div></div></div><h3 style="margin-top:20px">201 Documents</h3>${docs.map(d=>`<div class="list-row"><div><strong>${esc(d.name)}</strong><div class="small muted">${dateFmt(d.date)}</div></div>${badge(d.status||'Filed')}</div>`).join('')||'<div class="empty">No documents filed.</div>'}<h3 style="margin-top:20px">Recent DTR</h3>${att.map(a=>`<div class="list-row"><div><strong>${dateFmt(a.date)}</strong><div class="small muted">${esc(a.timeIn||'')} → ${esc(a.timeOut||'')}</div></div>${badge(a.status)}</div>`).join('')||'<div class="empty">No attendance records.</div>'}<h3 style="margin-top:20px">Payroll History</h3>${pays.map(p=>`<div class="list-row"><div><strong>${esc(p.employeeName)}</strong><div class="small muted">${esc(p.periodId)}</div></div><strong>${peso(p.netPay)}</strong></div>`).join('')||'<div class="empty">No payroll records.</div>'}</div></div></div>`}
function openDocumentForm(empId){$('#modalRoot').innerHTML=`<div class="modal-backdrop show"><div class="modal"><div class="modal-head"><h3>201 File Document</h3><button class="btn ghost" onclick="closeModal()">✕</button></div><form onsubmit="saveDocument(event,'${empId}')"><div class="modal-body"><div class="field"><label>Document Name</label><input name="name" placeholder="Employment Contract" required></div><div class="field"><label>Date Filed</label><input type="date" name="date" value="${new Date().toISOString().slice(0,10)}" required></div><div class="field"><label>Status</label><select name="status"><option>Filed</option><option>Pending</option><option>Expired</option></select></div><div class="field"><label>Attachment (optional)</label><input type="file" id="docFile" accept=".pdf,.jpg,.jpeg,.png,.doc,.docx"></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div></div><div class="modal-foot"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save</button></div></form></div></div>`}
async function saveDocument(e,empId){e.preventDefault();const obj=Object.fromEntries(new FormData(e.target).entries());obj.employeeId=empId;const f=$('#docFile')?.files?.[0];try{if(f){obj.fileName=f.name;obj.mime=f.type;obj.data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)})}await api('/api/documents',{method:'POST',body:JSON.stringify(obj)});closeModal();await load();toast('Document filed')}catch(err){toast(err.message)}}
function closeModal(){$('#modalRoot').innerHTML=''}

function timekeepingPage(){const rows=(state.data.attendance||[]).slice().sort((a,b)=>b.date.localeCompare(a.date));return `<div class="page-head"><div><h1>Timekeeping & DTR</h1><div class="muted">Attendance, biometric imports, manual adjustments, OT, holiday and night differential.</div></div><div class="actions"><button class="btn" onclick="openImportForm()">Import Biometrics CSV</button><button class="btn primary" onclick="openAttendanceForm()">＋ Encode Attendance</button></div></div><div class="card panel"><div class="toolbar"><input placeholder="Search employee/date/status…" value="${esc(state.query)}" oninput="state.query=this.value;renderPage()"/><button class="btn" onclick="downloadCSV('attendance')">Export DTR CSV</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Employee</th><th>Time In</th><th>Time Out</th><th>Status</th><th>Late</th><th>UT</th><th>OT</th><th>ND</th><th>Source</th><th>Action</th></tr></thead><tbody>${rows.filter(a=>JSON.stringify(a).toLowerCase().includes(state.query.toLowerCase())).map(a=>`<tr><td>${dateFmt(a.date)}</td><td>${esc(nameFor('employeeId',a.employeeId)||a.employeeNo)}</td><td>${esc(a.timeIn||'—')}</td><td>${esc(a.timeOut||'—')}</td><td>${badge(a.status)}</td><td>${safe(a.lateMinutes||0)}m</td><td>${safe(a.undertimeMinutes||0)}m</td><td>${Number(a.otHours||0).toFixed(2)}h</td><td>${Number(a.nightDiffHours||0).toFixed(2)}h</td><td>${esc(a.source||'manual')} ${a.adjustmentStatus==='Pending'?badge('Pending'):''}</td><td><div class="row-actions"><button class="btn" onclick="openAttendanceForm('${a.id}')">Edit</button>${a.adjustmentStatus==='Pending'&&has('timekeeping:approve')?`<button class="btn success" onclick="approveAttendance('${a.id}')">Approve</button>`:''}</div></td></tr>`).join('')||`<tr><td colspan="20"><div class="empty">No attendance records.</div></td></tr>`}</tbody></table></div></div>`}
function openAttendanceForm(id){const a=id?(state.data.attendance||[]).find(x=>x.id===id):{};$('#modalRoot').innerHTML=`<div class="modal-backdrop show"><div class="modal"><div class="modal-head"><h3>${id?'Edit':'Encode'} Attendance / DTR</h3><button class="btn ghost" onclick="closeModal()">✕</button></div><form onsubmit="saveAttendance(event,'${id||''}')"><div class="modal-body form-grid"><div class="field full"><label>Employee</label><select name="employeeId" required>${(state.data.employees||[]).map(e=>`<option value="${e.id}" ${a.employeeId===e.id?'selected':''}>${esc(e.employeeNo+' • '+e.firstName+' '+e.lastName)}</option>`).join('')}</select></div><div class="field"><label>Date</label><input type="date" name="date" value="${a.date||new Date().toISOString().slice(0,10)}" required></div><div class="field"><label>Status</label><select name="status"><option>Present</option><option ${a.status==='Late'?'selected':''}>Late</option><option ${a.status==='Absent'?'selected':''}>Absent</option><option ${a.status==='Holiday'?'selected':''}>Holiday</option><option ${a.status==='On Leave'?'selected':''}>On Leave</option></select></div><div class="field"><label>Time In</label><input type="time" name="timeIn" value="${a.timeIn||''}"></div><div class="field"><label>Time Out</label><input type="time" name="timeOut" value="${a.timeOut||''}"></div><div class="field"><label>Late Minutes</label><input type="number" name="lateMinutes" value="${a.lateMinutes||0}"></div><div class="field"><label>Undertime Minutes</label><input type="number" name="undertimeMinutes" value="${a.undertimeMinutes||0}"></div><div class="field"><label>OT Hours</label><input type="number" step="0.01" name="otHours" value="${a.otHours||0}"></div><div class="field"><label>Holiday Hours</label><input type="number" step="0.01" name="holidayHours" value="${a.holidayHours||0}"></div><div class="field"><label>Night Differential Hours</label><input type="number" step="0.01" name="nightDiffHours" value="${a.nightDiffHours||0}"></div><div class="field"><label>Source</label><input name="source" value="${esc(a.source||'manual')}" readonly></div><div class="field full"><label>Notes</label><textarea name="notes">${esc(a.notes||'')}</textarea></div></div><div class="modal-foot"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save Attendance</button></div></form></div></div>`}
async function saveAttendance(e,id){e.preventDefault();const o=Object.fromEntries(new FormData(e.target).entries());['lateMinutes','undertimeMinutes'].forEach(k=>o[k]=Number(o[k]||0));['otHours','holidayHours','nightDiffHours'].forEach(k=>o[k]=Number(o[k]||0));o.employeeNo=nameFor('employeeId',o.employeeId);try{await api(id?`/api/attendance/${id}`:'/api/attendance',{method:id?'PUT':'POST',body:JSON.stringify(o)});closeModal();await load();toast('DTR saved')}catch(err){toast(err.message)}}
async function approveAttendance(id){try{await api(`/api/attendance/${id}/approve`,{method:'POST'});await load();toast('Time adjustment approved')}catch(err){toast(err.message)}}
function openImportForm(){ $('#modalRoot').innerHTML=`<div class="modal-backdrop show"><div class="modal wide"><div class="modal-head"><h3>Biometrics / Timekeeping CSV Import</h3><button class="btn ghost" onclick="closeModal()">✕</button></div><div class="modal-body"><div class="notice">CSV columns supported: <b>employeeNo,date,timeIn,timeOut,status,lateMinutes,undertimeMinutes,otHours,holidayHours,nightDiffHours</b>. Use employee number from the masterlist.</div><div class="field"><label>CSV File</label><input type="file" id="csvFile" accept=".csv,text/csv"></div><div class="field"><label>Preview</label><textarea id="csvPreview" rows="12" placeholder="Select a CSV file"></textarea></div></div><div class="modal-foot"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="importCSVFile()">Import Records</button></div></div></div>`;$('#csvFile').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>$('#csvPreview').value=r.result;r.readAsText(f)})}
function parseCSV(txt){const lines=txt.replace(/^\uFEFF/,'').trim().split(/\r?\n/);if(lines.length<2)return[];const headers=lines[0].split(',').map(x=>x.trim().replace(/^"|"$/g,''));return lines.slice(1).map(line=>{const vals=[];let cur='',q=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){q=!q}else if(c===','&&!q){vals.push(cur);cur=''}else cur+=c}vals.push(cur);const o={};headers.forEach((h,i)=>o[h]=vals[i]?.trim()||'');return o})}
async function importCSVFile(){const txt=$('#csvPreview').value;try{const rows=parseCSV(txt);const r=await api('/api/import/attendance',{method:'POST',body:JSON.stringify({rows})});closeModal();await load();toast(`${r.added} attendance records imported`)}catch(err){toast(err.message)}}

function payrollPeriodsPage(){const rows=(state.data.payrollPeriods||[]).slice().sort((a,b)=>b.startDate.localeCompare(a.startDate));return `<div class="page-head"><div><h1>Payroll Periods / Cutoff</h1><div class="muted">Create, calculate, review and approve payroll periods.</div></div><div class="actions"><button class="btn primary" onclick="openPeriodForm()">＋ New Payroll Period</button></div></div><div class="card panel"><div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Frequency</th><th>Start</th><th>End</th><th>Pay Date</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(p=>`<tr><td><strong>${esc(p.name)}</strong></td><td>${esc(p.payFrequency)}</td><td>${dateFmt(p.startDate)}</td><td>${dateFmt(p.endDate)}</td><td>${dateFmt(p.payDate)}</td><td>${badge(p.status)}</td><td><div class="row-actions">${p.status!=='Approved'?`<button class="btn" onclick="generatePayroll('${p.id}')">${p.status==='Computed'?'Recalculate':'Generate'}</button>`:''}<button class="btn" onclick="viewPayroll('${p.id}')">View</button>${p.status==='Computed'&&has('payroll:approve')?`<button class="btn success" onclick="approvePayroll('${p.id}')">Approve</button>`:''}</div></td></tr>`).join('')||`<tr><td colspan="20"><div class="empty">No payroll periods yet.</div></td></tr>`}</tbody></table></div></div>`}
function openPeriodForm(){const d=new Date();const start=new Date(d.getFullYear(),d.getMonth(),1).toISOString().slice(0,10);const end=new Date(d.getFullYear(),d.getMonth()+1,0).toISOString().slice(0,10);$('#modalRoot').innerHTML=`<div class="modal-backdrop show"><div class="modal"><div class="modal-head"><h3>Create Payroll Period</h3><button class="btn ghost" onclick="closeModal()">✕</button></div><form onsubmit="savePeriod(event)"><div class="modal-body"><div class="field"><label>Name</label><input name="name" value="${d.toLocaleString('en',{month:'long'})} ${d.getFullYear()} Payroll" required></div><div class="field"><label>Frequency</label><select name="payFrequency"><option>Monthly</option><option>Semi-Monthly</option></select></div><div class="field"><label>Start Date</label><input type="date" name="startDate" value="${start}" required></div><div class="field"><label>End Date</label><input type="date" name="endDate" value="${end}" required></div><div class="field"><label>Pay Date</label><input type="date" name="payDate" value="${end}" required></div></div><div class="modal-foot"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Create Period</button></div></form></div></div>`}
async function savePeriod(e){e.preventDefault();const o=Object.fromEntries(new FormData(e.target).entries());o.status='Open';try{await api('/api/payrollPeriods',{method:'POST',body:JSON.stringify(o)});closeModal();await load();toast('Payroll period created')}catch(err){toast(err.message)}}
async function generatePayroll(id){try{const r=await api('/api/payroll/generate',{method:'POST',body:JSON.stringify({periodId:id})});await load();toast(`${r.records.length} employees calculated`);viewPayroll(id)}catch(err){toast(err.message)}}
async function approvePayroll(id){if(!confirm('Approve and lock this payroll period?'))return;try{await api(`/api/payroll/${id}/approve`,{method:'POST'});await load();toast('Payroll approved')}catch(err){toast(err.message)}}
function viewPayroll(id){state.page='payroll';state.query=id;render()}
function payrollPage(){const all=state.data.payrollRecords||[];const periodMap=Object.fromEntries((state.data.payrollPeriods||[]).map(p=>[p.id,p]));const rows=state.query?all.filter(r=>r.periodId===state.query):all.slice().reverse();const totals=rows.reduce((a,r)=>(a.gross+=Number(r.grossPay||0),a.net+=Number(r.netPay||0),a.sss+=Number(r.sssEE||0),a.ph+=Number(r.philhealthEE||0),a.pi+=Number(r.pagibigEE||0),a.tax+=Number(r.withholdingTax||0),a),{gross:0,net:0,sss:0,ph:0,pi:0,tax:0});return `<div class="page-head"><div><h1>Payroll</h1><div class="muted">Employee payroll computation, statutory deductions, deductions and employer costs.</div></div><div class="actions"><button class="btn" onclick="downloadCSV('payrollRecords')">Export Payroll CSV</button><button class="btn" onclick="go('payrollPeriods')">Payroll Periods</button></div></div><div class="grid kpis">${card('Gross Pay',peso(totals.gross))}${card('Net Pay',peso(totals.net))}${card('SSS EE',peso(totals.sss))}${card('PhilHealth EE',peso(totals.ph))}${card('Pag-IBIG EE',peso(totals.pi))}${card('Withholding Tax',peso(totals.tax))}</div><div class="card panel" style="margin-top:14px"><div class="toolbar"><select onchange="state.query=this.value;renderPage()"><option value="">All Payroll Periods</option>${(state.data.payrollPeriods||[]).map(p=>`<option value="${p.id}" ${state.query===p.id?'selected':''}>${esc(p.name)} • ${esc(p.status)}</option>`).join('')}</select></div><div class="table-wrap"><table class="table"><thead><tr><th>Employee</th><th>Regular</th><th>OT</th><th>Holiday</th><th>ND</th><th>Gross</th><th>Deductions</th><th>Net</th><th>Status</th><th>Payslip</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.employeeName)}</strong><div class="small muted">${esc(r.employeeNo)}</div></td><td>${peso(r.regularPay)}</td><td>${peso(r.overtimePay)}</td><td>${peso(r.holidayPay)}</td><td>${peso(r.nightDiffPay)}</td><td>${peso(r.grossPay)}</td><td>${peso(r.totalDeductions)}</td><td><strong>${peso(r.netPay)}</strong></td><td>${badge(r.status)}</td><td><button class="btn" onclick="showPayslip('${r.id}')">View</button></td></tr>`).join('')||`<tr><td colspan="20"><div class="empty">No payroll records. Create a period and generate payroll.</div></td></tr>`}</tbody></table></div></div>`}
function showPayslip(id){const p=(state.data.payrollRecords||[]).find(x=>x.id===id);if(!p)return;const e=(state.data.employees||[]).find(x=>x.id===p.employeeId);const period=(state.data.payrollPeriods||[]).find(x=>x.id===p.periodId);const c=state.settings.company;$('#modalRoot').innerHTML=`<div class="modal-backdrop show"><div class="modal"><div class="modal-head"><h3>Employee Payslip</h3><button class="btn ghost" onclick="closeModal()">✕</button></div><div class="modal-body" id="payslipPrint"><div style="display:flex;justify-content:space-between"><div><h2 style="margin:0">${esc(c.name)}</h2><div class="muted small">${esc(c.address||'Philippines')}</div></div><strong>PAYSLIP</strong></div><hr style="border:0;border-top:1px solid var(--line);margin:16px 0"><div class="grid stat-grid"><div><span class="small muted">Employee</span><div>${esc(p.employeeName)}</div></div><div><span class="small muted">Employee No.</span><div>${esc(p.employeeNo)}</div></div><div><span class="small muted">Period</span><div>${esc(period?.name||p.periodId)}</div></div><div><span class="small muted">Pay Date</span><div>${dateFmt(period?.payDate)}</div></div></div><h3 style="margin-top:20px">Earnings</h3>${[['Regular Pay',p.regularPay],['Overtime',p.overtimePay],['Holiday Pay',p.holidayPay],['Night Differential',p.nightDiffPay],['Allowances',p.allowances]].map(x=>`<div class="list-row"><span>${x[0]}</span><strong>${peso(x[1])}</strong></div>`).join('')}<div class="list-row"><strong>Gross Pay</strong><strong>${peso(p.grossPay)}</strong></div><h3 style="margin-top:20px">Deductions</h3>${[['Absences',p.absenceDeduction],['Late',p.lateDeduction],['Undertime',p.undertimeDeduction],['SSS',p.sssEE],['PhilHealth',p.philhealthEE],['Pag-IBIG',p.pagibigEE],['Withholding Tax',p.withholdingTax],['Loans',p.loanDeduction],['Other Deductions',p.otherDeduction]].map(x=>`<div class="list-row"><span>${x[0]}</span><strong>${peso(x[1])}</strong></div>`).join('')}<div class="list-row" style="margin-top:8px"><strong>NET PAY</strong><strong>${peso(p.netPay)}</strong></div></div><div class="modal-foot"><button class="btn" onclick="printPayslip()">Print</button><button class="btn primary" onclick="closeModal()">Close</button></div></div></div>`}
function printPayslip(){const html=$('#payslipPrint').innerHTML;const w=window.open('','_blank','width=800,height=900');w.document.write(`<html><head><title>Payslip</title><style>body{font-family:Arial;padding:28px;color:#18202d}.list-row{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid #ddd}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.muted{color:#687386}.small{font-size:12px}</style></head><body>${html}</body></html>`);w.document.close();w.focus();w.print()}
function payslipsPage(){const rows=(state.data.payrollRecords||[]).slice().reverse();return `<div class="page-head"><div><h1>Payslips</h1><div class="muted">Individual employee payslips with print-ready payroll breakdown.</div></div></div><div class="card panel"><div class="toolbar"><input placeholder="Search employee / period…" value="${esc(state.query)}" oninput="state.query=this.value;renderPage()"/></div><div class="table-wrap"><table class="table"><thead><tr><th>Employee</th><th>Period</th><th>Gross</th><th>Deductions</th><th>Net Pay</th><th>Action</th></tr></thead><tbody>${rows.filter(r=>JSON.stringify(r).toLowerCase().includes(state.query.toLowerCase())).map(r=>`<tr><td>${esc(r.employeeName)}</td><td>${esc(r.periodId)}</td><td>${peso(r.grossPay)}</td><td>${peso(r.totalDeductions)}</td><td><strong>${peso(r.netPay)}</strong></td><td><button class="btn" onclick="showPayslip('${r.id}')">View / Print</button></td></tr>`).join('')||`<tr><td colspan="10"><div class="empty">No payslips generated.</div></td></tr>`}</tbody></table></div></div>`}


let thirteenthRows=[]; async function thirteenthPage(){const year=new Date().getFullYear();return `<div class="page-head"><div><h1>13th Month Pay</h1><div class="muted">Compute based on basic salary earned from posted payroll history.</div></div><div class="actions"><input id="thYear" type="number" value="${year}" style="width:110px;padding:10px;border:1px solid var(--line);border-radius:11px;background:var(--surface);color:var(--text)"><button class="btn primary" onclick="calc13th()">Calculate</button></div></div><div class="card panel"><div id="thResult"><div class="empty">Click Calculate to generate 13th month figures.</div></div></div>`}
async function calc13th(){try{const y=Number($('#thYear').value||new Date().getFullYear());const r=await api('/api/payroll/13th-month',{method:'POST',body:JSON.stringify({year:y})});thirteenthRows=r.rows||[];$('#thResult').innerHTML=`<div class="toolbar"><button class="btn" onclick="downloadRows(thirteenthRows,'13th-month-${y}')">Export CSV</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Employee</th><th>Basic Salary Earned</th><th>13th Month</th></tr></thead><tbody>${thirteenthRows.map(x=>`<tr><td>${esc(x.employeeNo+' • '+x.employeeName)}</td><td>${peso(x.basicSalaryEarned)}</td><td><strong>${peso(x.thirteenthMonth)}</strong></td></tr>`).join('')||'<tr><td colspan="10"><div class="empty">No posted payroll records found for this year.</div></td></tr>'}</tbody></table></div><div class="list-row" style="margin-top:12px"><strong>Total 13th Month</strong><strong>${peso(r.total)}</strong></div>`}catch(err){toast(err.message)}}
function leavePage(){const rows=(state.data.leaveRequests||[]).slice().reverse();const emps=(state.data.employees||[]).filter(e=>e.status!=='Inactive');const lts=state.data.leaveTypes||[];const balances=emps.slice(0,8).map(e=>({e,vals:lts.map(t=>{const used=(state.data.leaveRequests||[]).filter(l=>l.employeeId===e.id&&l.leaveTypeId===t.id&&l.status==='Approved').reduce((s,l)=>s+Number(l.days||0),0);return {t,used,balance:Number(t.defaultDays||0)-used}})}));return `<div class="page-head"><div><h1>Leave Management</h1><div class="muted">Leave types, employee requests, balances, approval and history.</div></div><div class="actions"><button class="btn primary" onclick="openLeaveForm()">＋ New Leave Request</button></div></div>${panel('Leave Balance Overview',`<div class="table-wrap"><table class="table"><thead><tr><th>Employee</th>${lts.map(t=>`<th>${esc(t.code||t.name)}</th>`).join('')}</tr></thead><tbody>${balances.map(x=>`<tr><td>${esc(x.e.employeeNo+' • '+x.e.firstName+' '+x.e.lastName)}</td>${x.vals.map(v=>`<td><strong>${v.balance.toFixed(1)}</strong><div class="small muted">Used ${v.used.toFixed(1)} / ${Number(v.t.defaultDays||0).toFixed(1)}</div></td>`).join('')}</tr>`).join('')||'<tr><td colspan=10><div class="empty">No employees.</div></td></tr>'}</tbody></table></div>`)}<div class="card panel"><div class="table-wrap"><table class="table"><thead><tr><th>Employee</th><th>Type</th><th>Dates</th><th>Days</th><th>Reason</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(l=>`<tr><td>${esc(l.employeeName||nameFor('employeeId',l.employeeId))}</td><td>${esc(nameFor('leaveTypeId',l.leaveTypeId)||l.leaveTypeName||'')}</td><td>${dateFmt(l.startDate)} – ${dateFmt(l.endDate)}</td><td>${safe(l.days)}</td><td>${esc(l.reason||'')}</td><td>${badge(l.status)}</td><td>${l.status==='Pending'&&has('leave:approve')?`<div class="row-actions"><button class="btn success" onclick="decisionLeave('${l.id}','approve')">Approve</button><button class="btn danger" onclick="decisionLeave('${l.id}','reject')">Reject</button></div>`:'—'}</td></tr>`).join('')||`<tr><td colspan="20"><div class="empty">No leave requests.</div></td></tr>`}</tbody></table></div></div>`}
function openLeaveForm(){const lt=state.data.leaveTypes||[];$('#modalRoot').innerHTML=`<div class="modal-backdrop show"><div class="modal"><div class="modal-head"><h3>Leave Request</h3><button class="btn ghost" onclick="closeModal()">✕</button></div><form onsubmit="saveLeave(event)"><div class="modal-body"><div class="field"><label>Employee</label><select name="employeeId" required>${(state.data.employees||[]).filter(e=>e.status!=='Inactive').map(e=>`<option value="${e.id}">${esc(e.employeeNo+' • '+e.firstName+' '+e.lastName)}</option>`).join('')}</select></div><div class="field"><label>Leave Type</label><select name="leaveTypeId">${lt.map(x=>`<option value="${x.id}">${esc(x.name)} (${x.paid?'Paid':'Unpaid'})</option>`).join('')}</select></div><div class="field"><label>Start Date</label><input type="date" name="startDate" required></div><div class="field"><label>End Date</label><input type="date" name="endDate" required></div><div class="field"><label>Days</label><input type="number" step="0.5" name="days" value="1" required></div><div class="field"><label>Reason</label><textarea name="reason"></textarea></div></div><div class="modal-foot"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Submit Request</button></div></form></div></div>`}
async function saveLeave(e){e.preventDefault();const o=Object.fromEntries(new FormData(e.target).entries());o.days=Number(o.days||0);o.status='Pending';const emp=(state.data.employees||[]).find(x=>x.id===o.employeeId);o.employeeName=emp?emp.firstName+' '+emp.lastName:'';try{await api('/api/leaveRequests',{method:'POST',body:JSON.stringify(o)});closeModal();await load();toast('Leave request submitted')}catch(err){toast(err.message)}}
async function decisionLeave(id,decision){const c=decision==='approve'?'Approve':'Reject';if(!confirm(`${c} this leave request?`))return;try{await api(`/api/leave/${id}/decision`,{method:'POST',body:JSON.stringify({decision})});await load();toast(`Leave ${decision}d`)}catch(err){toast(err.message)}}
function loansPage(){const loans=state.data.loans||[], ded=state.data.deductions||[];return `<div class="page-head"><div><h1>Loans & Other Deductions</h1><div class="muted">Track loan balances, amortizations and recurring payroll deductions.</div></div><div class="actions"><button class="btn primary" onclick="openLoanForm('loan')">＋ Loan</button><button class="btn" onclick="openLoanForm('deduction')">＋ Deduction</button></div></div>${panel('Loans',tableLoans(loans,true))}${panel('Other Deductions',tableLoans(ded,false))}`}
function tableLoans(rows,isLoan){return `<div class="table-wrap"><table class="table"><thead><tr><th>Employee</th><th>${isLoan?'Loan Type':'Deduction'}</th><th>Amount</th><th>Amortization</th><th>Start</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(nameFor('employeeId',x.employeeId))}</td><td>${esc(x.type||x.name||'')}</td><td>${peso(x.amount||0)}</td><td>${peso(x.amortization||x.amount||0)}</td><td>${dateFmt(x.startDate)}</td><td>${badge(x.status||'Active')}</td><td><button class="btn danger" onclick="del('${isLoan?'loans':'deductions'}','${x.id}')">Delete</button></td></tr>`).join('')||`<tr><td colspan="20"><div class="empty">No records.</div></td></tr>`}</tbody></table></div>`}
function openLoanForm(kind){const isLoan=kind==='loan';$('#modalRoot').innerHTML=`<div class="modal-backdrop show"><div class="modal"><div class="modal-head"><h3>${isLoan?'Employee Loan':'Other Deduction'}</h3><button class="btn ghost" onclick="closeModal()">✕</button></div><form onsubmit="saveLoan(event,'${kind}')"><div class="modal-body"><div class="field"><label>Employee</label><select name="employeeId" required>${(state.data.employees||[]).map(e=>`<option value="${e.id}">${esc(e.employeeNo+' • '+e.firstName+' '+e.lastName)}</option>`).join('')}</select></div><div class="field"><label>${isLoan?'Loan Type':'Deduction Name'}</label><input name="${isLoan?'type':'name'}" value="${isLoan?'SSS Loan':'Uniform Deduction'}" required></div><div class="field"><label>Principal / Amount</label><input type="number" step="0.01" name="amount" required></div><div class="field"><label>Per Cutoff Amortization</label><input type="number" step="0.01" name="amortization" required></div><div class="field"><label>Start Date</label><input type="date" name="startDate" value="${new Date().toISOString().slice(0,10)}" required></div><div class="field"><label>Status</label><select name="status"><option>Active</option><option>Paused</option><option>Completed</option></select></div></div><div class="modal-foot"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save</button></div></form></div></div>`}
async function saveLoan(e,kind){e.preventDefault();const o=Object.fromEntries(new FormData(e.target).entries());o.amount=Number(o.amount||0);o.amortization=Number(o.amortization||0);const emp=(state.data.employees||[]).find(x=>x.id===o.employeeId);o.employeeName=emp?emp.firstName+' '+emp.lastName:'';try{await api(`/api/${kind==='loan'?'loans':'deductions'}`,{method:'POST',body:JSON.stringify(o)});closeModal();await load();toast('Saved')}catch(err){toast(err.message)}}

function reportsPage(){return `<div class="page-head"><div><h1>Reports Center</h1><div class="muted">Payroll, attendance, leave, contribution and accounting-ready reports.</div></div></div><div class="grid" style="grid-template-columns:repeat(3,1fr)">${[['payroll','Payroll Summary','Gross, net, statutory deductions'],['attendance','Attendance / DTR','Present, late, absent, OT'],['leave','Leave Report','Pending, approved, rejected'],['payroll','Payroll Register','Employee-level payroll detail'],['payroll','Accounting Report','Gross, employer costs, liabilities'],['attendance','Overtime Report','OT hours and OT pay'],['payroll','Contribution Report','SSS, PhilHealth, Pag-IBIG, tax'],['employee','Employee Report','Masterlist and organization'],['leave','13th Month Basis','Payroll history for 13th month']].map(x=>`<div class="card panel"><h3>${x[1]}</h3><div class="muted small">${x[2]}</div><button class="btn primary" style="margin-top:14px" onclick="runReport('${x[0]}','${esc(x[1])}')">Open Report</button></div>`).join('')}</div>`}
function runReport(type,title){let rows=[];if(type==='payroll')rows=state.data.payrollRecords||[];else if(type==='attendance')rows=state.data.attendance||[];else if(type==='leave')rows=state.data.leaveRequests||[];else rows=state.data.employees||[];$('#modalRoot').innerHTML=`<div class="modal-backdrop show"><div class="modal wide"><div class="modal-head"><h3>${title}</h3><button class="btn ghost" onclick="closeModal()">✕</button></div><div class="modal-body"><div class="notice">Report generated from current company-scoped records. Use Export for CSV or Print for a paper-ready view.</div><div class="table-wrap" style="margin-top:12px"><table class="table"><thead>${rows[0]?`<tr>${Object.keys(rows[0]).slice(0,10).map(k=>`<th>${esc(k)}</th>`).join('')}</tr>`:'<tr><th>Report</th></tr>'}</thead><tbody>${rows.slice(0,250).map(r=>`<tr>${Object.keys(rows[0]||{}).slice(0,10).map(k=>`<td>${esc(typeof r[k]==='object'?JSON.stringify(r[k]):r[k])}</td>`).join('')}</tr>`).join('')||'<tr><td><div class="empty">No data.</div></td></tr>'}</tbody></table></div></div><div class="modal-foot"><button class="btn" onclick="downloadRows(${JSON.stringify(rows).replace(/</g,'\\u003c')},'report')">Export CSV</button><button class="btn primary" onclick="window.print()">Print</button></div></div></div>`}

function securityPage(){const rows=state.data.users||[];return `<div class="page-head"><div><h1>Users & Access</h1><div class="muted">Role-based permissions for Admin, HR, Payroll, Accounting, Manager, Approver and Employee.</div></div><div class="actions"><button class="btn primary" onclick="openUserForm()">＋ Add User</button></div></div><div class="card panel"><div class="table-wrap"><table class="table"><thead><tr><th>User</th><th>Name</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(u=>`<tr><td>${esc(u.username)}</td><td>${esc(u.name)}</td><td>${badge(u.role)}</td><td>${badge(u.active===false?'Inactive':'Active')}</td><td><button class="btn" onclick="openUserForm('${u.id}')">Edit</button></td></tr>`).join('')}</tbody></table></div></div>`}
function openUserForm(id){const u=id?(state.data.users||[]).find(x=>x.id===id):{};$('#modalRoot').innerHTML=`<div class="modal-backdrop show"><div class="modal"><div class="modal-head"><h3>${id?'Edit User':'Add User'}</h3><button class="btn ghost" onclick="closeModal()">✕</button></div><form onsubmit="saveUser(event,'${id||''}')"><div class="modal-body"><div class="field"><label>Username</label><input name="username" value="${esc(u.username||'')}" required></div><div class="field"><label>Name</label><input name="name" value="${esc(u.name||'')}" required></div><div class="field"><label>Role</label><select name="role">${Object.keys({admin:1,hr:1,payroll:1,accounting:1,manager:1,approver:1,employee:1}).map(r=>`<option ${u.role===r?'selected':''}>${r}</option>`).join('')}</select></div><div class="field"><label>Password ${id?'(leave blank to keep current)':''}</label><input type="password" name="password" ${id?'':'required'}></div><div class="field"><label>Allowed Branch</label><select name="branchScope"><option value="all" ${!u.allowedBranchIds?.length?'selected':''}>All Branches</option>${(state.data.branches||[]).map(b=>`<option value="${b.id}" ${u.allowedBranchIds?.includes(b.id)?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><div class="field"><label>Active</label><select name="active"><option value="true" ${u.active!==false?'selected':''}>Active</option><option value="false" ${u.active===false?'selected':''}>Inactive</option></select></div></div><div class="modal-foot"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save</button></div></form></div></div>`}
async function saveUser(e,id){e.preventDefault();const o=Object.fromEntries(new FormData(e.target).entries());o.active=o.active==='true';o.allowedBranchIds=o.branchScope==='all'?[]:[o.branchScope];delete o.branchScope;if(!o.password)delete o.password;try{await api(id?`/api/users/${id}`:'/api/users',{method:id?'PUT':'POST',body:JSON.stringify(o)});closeModal();await load();toast('User saved')}catch(err){toast(err.message)}}
function auditPage(){const rows=state.data.audit||[];return `<div class="page-head"><div><h1>Audit Trail</h1><div class="muted">Trace logins, record changes, imports, payroll generation and approvals.</div></div></div><div class="card panel"><div class="table-wrap"><table class="table"><thead><tr><th>Date/Time</th><th>User</th><th>Action</th><th>Entity</th><th>Record ID</th><th>Details</th></tr></thead><tbody>${rows.slice().reverse().map(x=>`<tr><td>${new Date(x.createdAt).toLocaleString()}</td><td>${esc(x.username)}</td><td>${badge(x.action)}</td><td>${esc(x.entity)}</td><td>${esc(x.entityId)}</td><td><div class="small">${esc(JSON.stringify(x.detail||{}).slice(0,180))}</div></td></tr>`).join('')||`<tr><td colspan="20"><div class="empty">No audit events loaded.</div></td></tr>`}</tbody></table></div></div>`}
function settingsPage(){const s=state.settings;return `<div class="page-head"><div><h1>Payroll & Company Settings</h1><div class="muted">Statutory contribution tables and payroll rules are configurable.</div></div></div><div class="grid dashboard-grid"><div>${panel('Company Profile',settingsForm('company',s.company))}${panel('Payroll Rules',settingsForm('payroll',s.payroll))}</div><div>${panel('SSS',settingsForm('sss',s.sss))}${panel('PhilHealth',settingsForm('philhealth',s.philhealth))}${panel('Pag-IBIG',settingsForm('pagibig',s.pagibig))}${panel('BIR / Tax',settingsForm('tax',s.tax))}${panel('Biometric Integration',settingsForm('biometrics',s.biometrics||{}))}</div></div>`}
function settingsForm(group,obj){return `<form onsubmit="saveSettings(event,'${group}')"><div class="form-grid">${Object.entries(obj).map(([k,v])=>`<div class="field"><label>${esc(k)}</label>${typeof v==='boolean'?`<select name="${esc(k)}"><option value="true" ${v?'selected':''}>Enabled</option><option value="false" ${!v?'selected':''}>Disabled</option></select>`:`<input name="${esc(k)}" value="${esc(v)}" type="${typeof v==='number'?'number':'text'}" step="${typeof v==='number'?'0.01':'1'}">`}</div>`).join('')}</div><button class="btn primary">Save ${esc(group)}</button></form>`}
async function saveSettings(e,group){e.preventDefault();const o={};for(const [k,v] of new FormData(e.target).entries()){const old=state.settings[group]?.[k];o[k]=typeof old==='number'?Number(v):typeof old==='boolean'?v==='true':v}try{await api('/api/settings',{method:'POST',body:JSON.stringify({[group]:o})});await load();toast('Settings updated')}catch(err){toast(err.message)}}
function reportPlaceholder(){return `<div class="card panel"><div class="empty">Select a report from Reports Center.</div></div>`}
function closeIf(e){}
async function del(resource,id){if(!confirm('Delete this record?'))return;try{await api(`/api/${resource}/${id}`,{method:'DELETE'});await load();toast('Deleted')}catch(err){toast(err.message)}}
function openGenericForm(kind,id){const cfg=entityConfig[kind], row=id?(state.data[cfg.key]||[]).find(x=>x.id===id):{};$('#modalRoot').innerHTML=`<div class="modal-backdrop show"><div class="modal"><div class="modal-head"><h3>${id?'Edit':'Add'} ${cfg.title.replace(/s$/,'')}</h3><button class="btn ghost" onclick="closeModal()">✕</button></div><form onsubmit="saveGeneric(event,'${kind}','${id||''}')"><div class="modal-body">${cfg.fields.map(f=>{const [k,l,t]=f;let val=row[k];if(k==='restDays'&&Array.isArray(val))val=val.join(',');if(t==='checkbox')return `<div class="field"><label>${l}</label><select name="${k}"><option value="true" ${val!==false?'selected':''}>Yes</option><option value="false" ${val===false?'selected':''}>No</option></select></div>`;if(t.startsWith('selectOptions:'))return `<div class="field"><label>${l}</label><select name="${k}">${t.split(':')[1].split('|').map(x=>`<option ${val===x?'selected':''}>${x}</option>`).join('')}</select></div>`;if(t.startsWith('select:'))return `<div class="field"><label>${l}</label><select name="${k}">${(state.data[t.split(':')[1]]||[]).map(x=>`<option value="${x.id}" ${val===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>`;return `<div class="field"><label>${l}</label><input name="${k}" type="${t}" value="${esc(Array.isArray(val)?val.join(','):val??'')}"></div>`}).join('')}</div><div class="modal-foot"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save</button></div></form></div></div>`}
async function saveGeneric(e,kind,id){e.preventDefault();const cfg=entityConfig[kind],o=Object.fromEntries(new FormData(e.target).entries());cfg.fields.forEach(([k,l,t])=>{if(t==='checkbox')o[k]=o[k]==='true';if(t==='number')o[k]=Number(o[k]||0);if(k==='restDays')o[k]=(o[k]||'').split(',').map(x=>Number(x.trim())).filter(x=>Number.isFinite(x))});try{await api(id?`/api/${cfg.key}/${id}`:`/api/${cfg.key}`,{method:id?'PUT':'POST',body:JSON.stringify(o)});closeModal();await load();toast('Saved')}catch(err){toast(err.message)}}
function downloadCSV(resource){const url=`/api/export?resource=${encodeURIComponent(resource)}`;const a=document.createElement('a');a.href=url;const token=state.token;fetch(url,{headers:{'x-session-token':token}}).then(r=>r.blob()).then(b=>{a.href=URL.createObjectURL(b);a.download=`${resource}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}).catch(err=>toast(err.message))}
function downloadRows(rows,name){const csv=exportRows(rows);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`${name}.csv`;a.click()}
function exportRows(rows){if(!rows.length)return'';const keys=[...new Set(rows.flatMap(Object.keys))];const q=v=>`"${String(v??'').replace(/"/g,'""')}"`;return keys.join(',')+'\n'+rows.map(r=>keys.map(k=>q(typeof r[k]==='object'?JSON.stringify(r[k]):r[k])).join(',')).join('\n')}

const originalRender=render;
render=()=>{originalRender();if(state.token&&!state.user)load()};
if(state.token)load();else render();
